// Текст документа для базы знаний компании Sun Rent
// Содержит информацию об аренде автомобилей в Испании
const documentText = `Компания Sun Rent предоставляет услуги по аренде автомобилей в Испании с 2015 года. Мы работаем в 15 городах: Барселона, Мадрид, Валенсия, Малага, Тенерифе и других. Автопарк насчитывает более 500 автомобилей от эконом до премиум класса.

Условия аренды. Минимальный срок аренды — 3 дня, максимальный — 45 дней. Для подтверждения бронирования нужна предоплата 25% от стоимости. Полная оплата — при получении автомобиля. Принимаем карты Visa, MasterCard и МИР.

Требования к арендатору. Минимальный возраст — 21 год, стаж вождения — от 2 лет. Нужны водительское удостоверение международного образца и паспорт. Для автомобилей премиум класса минимальный возраст — 25 лет.

Страховка. Базовая страховка включена в стоимость — покрывает ДТП и кражу. Полная страховка без франшизы — 15 евро в сутки. Страховка не покрывает ущерб от алкоголя и нарушений ПДД.

Возврат автомобиля. Верните автомобиль в том же состоянии. Заправка за счёт арендатора. При неполном баке доплата 50 евро. Возврат в другом городе — 75 евро.

Дополнительные услуги. Детское кресло — 8 евро/сутки. Навигатор — 5 евро/сутки. Дополнительный водитель — 10 евро/сутки. Доставка в аэропорт — 25 евро. Зимние шины (ноябрь-март) — 7 евро/сутки.

Отмена бронирования. За 72+ часа — полный возврат. За 24-72 часа — 50% возврат. Менее 24 часов — предоплата не возвращается.

Контакты. Телефон: +34 900 123 456. Email: support@sunrent.ru. WhatsApp: +34 600 123 456. Работаем ежедневно 9:00-21:00 по мадридскому времени.`;

// Возвращаем документ в формате, понятном для n8n
return [{ json: { text: documentText } }];

// Получаем текст документа из предыдущей ноды
const text = $input.first().json.text;

// Параметры нарезки
const chunkSize = 500; // Размер фрагмента в символах
const chunkOverlap = 50; // Перекрытие между фрагментами

// Массив для хранения фрагментов
const chunks = [];

// Нарезаем текст на фрагменты
for (let i = 0; i < text.length; i += chunkSize - chunkOverlap) {
  // Извлекаем фрагмент текста
  const chunk = text.substring(i, i + chunkSize);
  // Добавляем фрагмент, если он не пустой
  if (chunk.trim().length > 0) {
    chunks.push({ json: { text: chunk, chunkIndex: chunks.length } });
  }
}

// Возвращаем массив фрагментов
return chunks;

// Получаем токен авторизации из предыдущей ноды
const token = $input.first().json.body.access_token;

// Проходим по всем фрагментам документа
const items = $input.all();
const results = [];

for (const item of items) {
  // К каждому фрагменту добавляем токен для последующей авторизации
  results.push({
    json: {
      text: item.json.text || item.json.chunk,
      token: token
    }
  });
}

// Возвращаем массив фрагментов с токеном
return results;

// Получаем результаты создания эмбеддингов
const items = $input.all();

// Получаем исходные фрагменты с текстом из предыдущей ноды
const prevItems = $('Добавить токен к чанкам').all();

// Массив для хранения точек, готовых к загрузке в Qdrant
const points = [];

// Проходим по каждому результату эмбеддинга
for (let i = 0; i < items.length; i++) {
  // Извлекаем вектор (эмбеддинг) из ответа API
  const embedding = items[i].json.body?.data?.[0]?.embedding;
  // Извлекаем соответствующий текст фрагмента
  const text = prevItems[i]?.json?.text;

  // Если и вектор, и текст успешно извлечены
  if (embedding && text) {
    // Формируем точку для Qdrant: id, вектор и текст в payload
    points.push({
      id: i + 1,
      vector: embedding,
      payload: { text: text, source: 'faq' }
    });
  }
}

// Возвращаем собранные точки и их количество
return [{ json: { points: points, count: points.length } }];

// Извлекаем текст вопроса из чата
const query = $input.first().json.chatInput;

// Получаем токен авторизации из предыдущей ноды
const token = $('Токен GigaChat (для вопроса)').first().json.body.access_token;

// Возвращаем объект с вопросом и токеном
return [{ json: { query: query, token: token } }];

// Извлекаем вектор вопроса из ответа API эмбеддингов
const vector = $input.first().json.body?.data?.[0]?.embedding;

// Получаем исходный текст вопроса из ноды подготовки
const query = $('Подготовка').first().json.query;

// Возвращаем вектор и вопрос для поиска в Qdrant
return [{ json: { vector: vector, query: query } }];

// Получаем результаты поиска из Qdrant
const results = $input.first().json.body?.result;

// Получаем исходный вопрос пользователя
const query = $('Собрать запрос').first().json.query;

// Если результатов нет — сообщаем об этом
if (!results || results.length === 0) {
  return [{ json: { context: 'Информация не найдена', query: query, found: false } }];
}

// Собираем тексты найденных фрагментов в один контекст
const ctx = results.map((r, i) => `[${i+1}] ${r.payload?.text}`).join('\n\n');

// Возвращаем собранный контекст и вопрос
return [{ json: { context: ctx, query: query, found: true } }];
